function loadScript(){let n=arguments;for(let e=0,t=n.length;e<t;e++){var a=n[e];var r=document.createElement("script");r.type="text/javascript";r.charset="UTF-8";r.async=true;r.src=a;document.head.appendChild(r)}}function loadScriptDefer(){let n=arguments;for(let e=0,t=n.length;e<t;e++){var a=n[e];var r=document.createElement("script");r.type="text/javascript";r.charset="UTF-8";r.defer=true;r.src=a;document.head.appendChild(r)}}function loadCss(){let n=arguments;for(let e=0,t=n.length;e<t;e++){var a=n[e];var r=document.createElement("link");r.rel="stylesheet";r.href=a;document.head.appendChild(r)}}function loadScriptHandler(e,t){var n=document.createElement("script");n.type="text/javascript";n.charset="UTF-8";n.src=e;if(n.addEventListener){n.addEventListener("load",function(){t()},false)}else if(n.attachEvent){n.attachEvent("onreadystatechange",function(){var e=window.event.srcElement;if(e.readyState==="loaded"){t()}})}document.head.appendChild(n)}window.getRootUrl=function(){var e=window.location.origin;var t=window.location.pathname;return e+"/"+t.split("/")[1]};function getDefaultLang(){let e=getUrlParam("locale");if(!e){e=localStorage.getItem("lang")}if(!e){e=navigator.language;e=e.replace("-","_")}if(!e){e="zh_CN"}return e}function getUrlParam(n){let e=window.location.href;let a=e.split("?");for(let e=a.length-1;e>0;e--){const r=a[e];if(!r||r.indexOf("=")<0){continue}let t=r.split("&");for(let e=0;e<t.length;e++){const l=t[e];if(l.split("=")[0]===n){return l.split("=")[1]}}}return null}